+	const conversationId = (ctx.mcpConversationId ?? ctx.mcpSessionId)?.trim();
+	if (!conversationId || conversationId.length > MAX_CONVERSATION_ID_LENGTH) {
+		return null;
+	}
+	return {
+		clientIdentity: ctx.clientId?.trim() || "",
+		conversationId,
+	};
+}
+
+export function normalizeMcpConversationTitle(value: string): string {
+	return value
+		.replace(/[\u0000-\u001f\u007f]/g, " ")
+		.replace(/\s+/g, " ")
+		.trim()
+		.slice(0, MAX_TITLE_LENGTH);
+}
+
+function actionLabel(toolName: string): string {
+	const declared = getTool(toolName)?.annotations?.title;
+	if (typeof declared === "string" && declared.trim()) return declared.trim();
+	return toolName
+		.split("_")
+		.filter(Boolean)
+		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
+		.join(" ");
+}
+
+/** Best-effort write-time projection for one MCP host conversation. */
+export async function recordMcpConversationActivity(args: {
