+        organization_id, client_identity, conversation_id,
+        transport_session_id, client_id, user_id, agent_id,
+        last_action, tools, call_count, failed_count
+      ) VALUES (
+        ${args.ctx.organizationId}, ${identity.clientIdentity},
+        ${identity.conversationId}, ${args.ctx.mcpSessionId ?? null},
+        ${args.ctx.clientId ?? null}, ${args.ctx.userId ?? null},
+        ${args.ctx.agentId ?? null}, ${label}, ${JSON.stringify([args.toolName])}::jsonb,
+        1, ${args.failed ? 1 : 0}
+      )
+      ON CONFLICT (organization_id, client_identity, conversation_id)
