+
+/** Recent org-wide MCP conversations from the write-time projection. */
+const routes = new Hono<{ Bindings: Env }>();
+
+const ACTIVITY_WINDOW_DAYS = 14;
+
+interface SessionRow {
+	conversation_id: string;
+	transport_session_id: string | null;
+	client_id: string | null;
+	client_name: string | null;
+	user_id: string | null;
+	agent_id: string | null;
+	title: string | null;
+	last_action: string;
+	first_activity_at: Date;
+	last_activity_at: Date;
+	call_count: number;
+	failed_count: number;
+	tools: unknown;
+	pending_interaction_count: number;
+}
+
+function stringArray(value: unknown): string[] {
+	return Array.isArray(value)
+		? value.filter((item): item is string => typeof item === "string")
+		: [];
+}
+
+routes.get("/", mcpAuth, async (c) => {
+	const organizationId = c.get("organizationId") as string | undefined;
+	if (!organizationId) {
+		return c.json({ error: "Organization required" }, 401);
+	}
+	const rawLimit = Number.parseInt(c.req.query("limit") ?? "20", 10);
+	const limit = Math.min(
+		Math.max(Number.isNaN(rawLimit) ? 20 : rawLimit, 1),
+		100,
+	);
+
+	const sql = getDb();
+	const rows = await sql<SessionRow>`
+    SELECT
+      mc.conversation_id,
+      mc.transport_session_id,
+      mc.client_id,
+      oc.client_name,
+      mc.user_id,
+      mc.agent_id,
+      mc.title,
+      mc.last_action,
+      mc.first_activity_at,
+      mc.last_activity_at,
+      mc.call_count,
+      mc.failed_count,
+      mc.tools,
+      COALESCE((
+        SELECT count(*)::integer
+        FROM current_event_records a
+        WHERE a.organization_id = mc.organization_id
+          AND a.interaction_type <> 'none'
+          AND a.interaction_status = 'pending'
+          AND a.metadata->>'mcp_session_id' = mc.transport_session_id
+      ), 0)::integer AS pending_interaction_count
+    FROM public.mcp_client_conversations mc
+    LEFT JOIN oauth_clients oc ON oc.id = mc.client_id
+    WHERE mc.organization_id = ${organizationId}
+      AND mc.last_activity_at > now() - make_interval(days => ${ACTIVITY_WINDOW_DAYS})
+    ORDER BY mc.last_activity_at DESC
+    LIMIT ${limit}
+  `;
+
+	return c.json({
